/**
 * Fuzz of the font layer, called directly: `to-unicode.ts#readToUnicode`, `font-text.ts#fontText`,
 * `predefined-cmaps.ts#unicodeCodes` and `#textOfUnicodeCode`. Lot 4 of the PDF fuzz design (16/11/2026).
 * Input: a code→text table generated by fast-check, written as a `/ToUnicode` CMap by a test writer made from
 * ISO 32000-1:2008 (§9.10.3 and its Example, §9.7.5 CMap syntax, §7.3.4.3 hexadecimal strings) in its three forms:
 * `bfchar`, `bfrange` with a string, `bfrange` with an array; and the real `/ToUnicode` CMaps of three fixtures,
 * damaged.
 * Properties: the table read equals the model; the text never holds a lone surrogate nor U+0000 (an invented
 * character); damaged bytes give a table or a refusal of ours, never a raw error.
 *
 * The seed is fixed (`PDF_FUZZ_SEED`): a red run replays as is. The run counts are the written ones, times the weekly
 * multiplier (`lib/pdf-fuzz-runs.test.support.ts`).
 * NOT covered: a CONTROL character. The font layer gives the one a CMap declares (`<01> <0007>` reads "\u0007"), and
 * only a glyph whose whole text is control characters is dropped later (`glyph-positions.ts#isInventedControl`):
 * reported on 24/11/2026, not decided here. Glyph names (`names.ts`) and widths are not fuzzed here.
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import fc from "fast-check";
import { describe, expect, it, vi } from "vitest";

import { openPdfObjects } from "../pdf-objects/document";
import type { PdfDict, PdfStream, PdfValue } from "../pdf-objects/objects";
import { PdfObjectsRefusal } from "../pdf-objects/refusal";
import { Choices, drawsArb } from "../pdf-objects/pdf-syntax-writer.test.support";
import { fontText, type FontReader } from "./font-text";
import { textOfUnicodeCode, unicodeCodes } from "./predefined-cmaps";
import { readToUnicode } from "./to-unicode";
import { PDF_FUZZ_SEED } from "../pdf-fuzz-outcome.test.support";
import { fuzzRuns, fuzzTestTimeout } from "../../lib/pdf-fuzz-runs.test.support";

vi.setConfig({ testTimeout: fuzzTestTimeout(30000, process.env) });

const params = (baseRuns: number): fc.Parameters<unknown> => ({
  numRuns: fuzzRuns(baseRuns, process.env),
  seed: PDF_FUZZ_SEED,
  timeout: 8000,
});

const latin1 = (text: string): Uint8Array => Uint8Array.from(text, (char) => char.charCodeAt(0));

// ---------------------------------------------------------------------------------------------------------------------
// The model and its expected reading.

/** One piece of a CMap: a `bfchar` entry, a `bfrange` whose destination string is incremented, or a `bfrange` with one
 *  destination per code (§9.10.3). Destinations are UTF-16BE units. */
type Segment =
  | { readonly kind: "char"; readonly code: number; readonly units: readonly number[] }
  | { readonly kind: "string"; readonly first: number; readonly count: number; readonly units: readonly number[] }
  | { readonly kind: "array"; readonly first: number; readonly destinations: readonly (readonly number[])[] };

interface TableModel {
  /** Bytes per code (§9.7.6.2: one to four). */
  readonly width: number;
  readonly segments: readonly Segment[];
}

const isHigh = (unit: number): boolean => unit >= 0xd800 && unit <= 0xdbff;
const isLow = (unit: number): boolean => unit >= 0xdc00 && unit <= 0xdfff;

/** A text an extractor may publish: no U+0000, every surrogate in a pair (§9.10.3: UTF-16BE spells characters). */
function isPublishable(text: string): boolean {
  for (let i = 0; i < text.length; i += 1) {
    const unit = text.charCodeAt(i);
    if (unit === 0 || isLow(unit)) return false;
    if (isHigh(unit)) {
      if (!isLow(text.charCodeAt(i + 1))) return false;
      i += 1;
    }
  }
  return true;
}

/** The text the reader must give for a destination: the characters it spells, or nothing when it would spell a U+0000
 *  or a lone surrogate (the reader's written filter, `to-unicode.ts#isWellFormed`). */
function expectedText(units: readonly number[]): string {
  const text = String.fromCharCode(...units);
  return isPublishable(text) ? text : "";
}

/** code → destination units, as §9.10.3 defines each form. */
function modelUnits(model: TableModel): Map<number, readonly number[]> {
  const table = new Map<number, readonly number[]>();
  for (const segment of model.segments) {
    if (segment.kind === "char") table.set(segment.code, segment.units);
    else if (segment.kind === "array") segment.destinations.forEach((units, i) => table.set(segment.first + i, units));
    else
      for (let i = 0; i < segment.count; i += 1) {
        const units = [...segment.units];
        units[units.length - 1] = (units[units.length - 1] as number) + i;
        table.set(segment.first + i, units);
      }
  }
  return table;
}

// ---------------------------------------------------------------------------------------------------------------------
// The generator.

/** A destination: mostly real characters (Latin, Greek, CJK, a ligature, an astral pair), sometimes a U+0000 or a lone
 *  half-pair that the reader must drop. */
const unitArb: fc.Arbitrary<number[]> = fc.oneof(
  { weight: 6, arbitrary: fc.integer({ min: 0x20, max: 0x24f }).map((u) => [u]) },
  { weight: 2, arbitrary: fc.integer({ min: 0x370, max: 0xd7ff }).map((u) => [u]) },
  { weight: 2, arbitrary: fc.integer({ min: 0xe000, max: 0xfffd }).map((u) => [u]) },
  {
    weight: 2,
    arbitrary: fc
      .integer({ min: 0x10000, max: 0x10ffff })
      .map((cp) => [0xd800 + ((cp - 0x10000) >> 10), 0xdc00 + ((cp - 0x10000) & 0x3ff)]),
  },
  { weight: 1, arbitrary: fc.constantFrom(0, 0xd800, 0xdbff, 0xdc00, 0xdfff).map((u) => [u]) },
);

/** One to four characters (MAX_TOUNICODE_UNITS is eight units). */
const destinationArb: fc.Arbitrary<number[]> = fc
  .array(unitArb, { minLength: 1, maxLength: 3 })
  .map((parts) => parts.flat().slice(0, 8));

interface SegmentDraft {
  readonly kind: Segment["kind"];
  readonly length: number;
  readonly gap: number;
  readonly destinations: readonly number[][];
}

const draftArb: fc.Arbitrary<SegmentDraft> = fc.record({
  kind: fc.constantFrom<Segment["kind"]>("char", "string", "array"),
  length: fc.integer({ min: 1, max: 40 }),
  gap: fc.integer({ min: 0, max: 300 }),
  destinations: fc.array(destinationArb, { minLength: 1, maxLength: 40 }),
});

/** Segments on disjoint code intervals, in increasing order. A range stays inside one block of 256 codes (its first and
 *  last code differ in their last byte only, as in the Example of §9.10.3), and an incremented destination keeps its last
 *  BYTE under 256 (§9.10.3: "the value of the last byte in the string shall be less than or equal to 255 − (srcCode2 −
 *  srcCode1)"). */
function segmentsOf(width: number, start: number, drafts: readonly SegmentDraft[]): Segment[] {
  const limit = 256 ** width;
  const segments: Segment[] = [];
  let cursor = start % limit;
  for (const draft of drafts) {
    const room = Math.min(256 - (cursor % 256), limit - cursor);
    if (room <= 0 || cursor >= limit) break;
    const first = draft.destinations[0] as number[];
    if (draft.kind === "char") segments.push({ kind: "char", code: cursor, units: first });
    else if (draft.kind === "array") {
      const destinations = draft.destinations.slice(0, Math.min(room, draft.length));
      segments.push({ kind: "array", first: cursor, destinations });
    } else {
      const lastByte = (first[first.length - 1] as number) & 0xff;
      const count = Math.max(1, Math.min(room, draft.length, 256 - lastByte));
      segments.push({ kind: "string", first: cursor, count, units: first });
    }
    const used = segments[segments.length - 1] as Segment;
    const span = used.kind === "char" ? 1 : used.kind === "array" ? used.destinations.length : used.count;
    cursor += span + draft.gap;
  }
  return segments;
}

const tableArb: fc.Arbitrary<TableModel> = fc
  .record({
    width: fc.constantFrom(1, 2, 2, 2, 3, 4),
    start: fc.nat(),
    drafts: fc.array(draftArb, { minLength: 1, maxLength: 12 }),
  })
  .map(({ width, start, drafts }) => ({ width, segments: segmentsOf(width, start, drafts) }));

// ---------------------------------------------------------------------------------------------------------------------
// The writer.

/** §7.3.4.3: two hexadecimal digits per byte, either case, white space allowed between digits. */
function hex(bytes: readonly number[], choices: Choices): string {
  let text = "<";
  for (const byte of bytes) {
    let pair = byte.toString(16).padStart(2, "0");
    if (choices.chance(50)) pair = pair.toUpperCase();
    text += (choices.chance(5) ? " " : "") + pair;
  }
  return `${text}>`;
}

const codeBytes = (code: number, width: number): number[] =>
  Array.from({ length: width }, (_, i) => (code >>> (8 * (width - 1 - i))) & 0xff);

const unitBytes = (units: readonly number[]): number[] => units.flatMap((unit) => [unit >> 8, unit & 0xff]);

const SPACE = [" ", "\n", "\r\n", "\t", "  "];

function segmentLine(segment: Segment, width: number, choices: Choices): string {
  const gap = (): string => choices.oneOf(SPACE);
  if (segment.kind === "char")
    return hex(codeBytes(segment.code, width), choices) + gap() + hex(unitBytes(segment.units), choices);
  const first = segment.first;
  const count = segment.kind === "string" ? segment.count : segment.destinations.length;
  const range = hex(codeBytes(first, width), choices) + gap() + hex(codeBytes(first + count - 1, width), choices);
  if (segment.kind === "string") return range + gap() + hex(unitBytes(segment.units), choices);
  const items = segment.destinations.map((units) => hex(unitBytes(units), choices)).join(gap());
  return `${range}${gap()}[${choices.chance(30) ? " " : ""}${items}]`;
}

/** §9.7.5 and the Example of §9.10.3: the header producers write, a code space range of the table's width, the
 *  segments in `bfchar` and `bfrange` blocks of at most 100 entries, interleaved at random, then the footer. */
function writeCMap(model: TableModel, choices: Choices): Uint8Array {
  const lowCode = hex(codeBytes(0, model.width), choices);
  const highCode = hex(codeBytes(256 ** model.width - 1, model.width), choices);
  const blocks: string[] = [];
  let pending: { kind: "bfchar" | "bfrange"; lines: string[] } | undefined;
  const flush = (): void => {
    if (pending === undefined) return;
    blocks.push(`${pending.lines.length} begin${pending.kind}\n${pending.lines.join("\n")}\nend${pending.kind}`);
    pending = undefined;
  };
  for (const segment of model.segments) {
    const kind = segment.kind === "char" ? "bfchar" : "bfrange";
    if (pending?.kind !== kind || pending.lines.length >= 100 || choices.chance(20)) flush();
    pending ??= { kind, lines: [] };
    pending.lines.push(segmentLine(segment, model.width, choices));
  }
  flush();
  return latin1(`/CIDInit /ProcSet findresource begin
12 dict begin
begincmap
/CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def
/CMapName /Adobe-Identity-UCS def
/CMapType 2 def
1 begincodespacerange
${lowCode} ${highCode}
endcodespacerange
${blocks.join("\n")}
endcmap
CMapName currentdict /CMap defineresource pop
end
end
`);
}

// ---------------------------------------------------------------------------------------------------------------------
// The properties on generated tables.

const caseArb = fc.record({ model: tableArb, draws: drawsArb });

/** A font reader over one stream: what `fontText` needs of a document. */
function readerOver(data: Uint8Array): { reader: FontReader; stream: PdfStream } {
  const stream: PdfStream = { kind: "stream", dict: new Map(), start: 0, length: data.length };
  const reader: FontReader = {
    resolve: (value) => value,
    dictOf: (value) => (value?.kind === "dict" ? value.entries : undefined),
    streamBytes: () => data,
  };
  return { reader, stream };
}

const name = (value: string): PdfValue => ({ kind: "name", value });

describe("readToUnicode - generated tables written as a CMap (9.10.3)", () => {
  it("reads the table the model holds, in its three forms", () => {
    fc.assert(
      fc.property(caseArb, ({ model, draws }) => {
        const read = readToUnicode(writeCMap(model, new Choices(draws)));
        const units = modelUnits(model);
        const expected = new Map([...units].map(([code, u]) => [code, expectedText(u)]));
        expect(read.text).toEqual(expected);
        // What the filter dropped is still declared, for the pairing of neighbouring codes (`pdf-glyph-source.ts`).
        const rejected = new Map(
          [...units].flatMap(([code, u]) =>
            expectedText(u) === "" ? [[code, String.fromCharCode(...u)] as const] : [],
          ),
        );
        expect(read.rejected).toEqual(rejected);
      }),
      params(200),
    );
  });

  it("fontText gives the table's text for each code, never a lone surrogate nor U+0000 (9.10.2)", () => {
    fc.assert(
      fc.property(caseArb, fc.boolean(), ({ model, draws }, composite) => {
        const { reader, stream } = readerOver(writeCMap(model, new Choices(draws)));
        const font: PdfDict = new Map<string, PdfValue>([
          ["Subtype", name(composite ? "Type0" : "TrueType")],
          ["ToUnicode", stream],
          ...(composite ? [["Encoding", name("Identity-H")] as const] : []),
        ]);
        const textOf = fontText(reader, font);
        for (const [code, units] of modelUnits(model)) {
          const text = textOf(code);
          expect(text, `code ${code}`).toBe(expectedText(units));
          expect(isPublishable(text ?? ""), `code ${code}: an invented character`).toBe(true);
        }
      }),
      params(150),
    );
  });
});

// ---------------------------------------------------------------------------------------------------------------------
// Real CMaps, damaged.

const here = dirname(fileURLToPath(import.meta.url));

/** The `/ToUnicode` CMaps of the fonts of every page of a fixture, decoded by the reader. English first (the corpus
 *  rule), then French. */
function realCMaps(file: string): Uint8Array[] {
  const doc = openPdfObjects(new Uint8Array(readFileSync(join(here, "../../../fixtures/pdf", file))));
  const found = new Map<number, Uint8Array>();
  for (const page of doc.pages()) {
    for (const [, font] of doc.dictOf(page.resources?.get("Font")) ?? []) {
      const stream = doc.resolve(doc.dictOf(font)?.get("ToUnicode"));
      // Copied: a decoded stream may be a Buffer, whose `slice` is a view, and the damage must never reach the seed.
      if (stream?.kind === "stream" && !found.has(stream.start))
        found.set(stream.start, Uint8Array.from(doc.streamBytes(stream)));
    }
  }
  return [...found.values()];
}

const SEEDS: readonly Uint8Array[] = [
  "40-School-Improvement-Planning-Word365.pdf",
  "14-Ligatures-ToUnicode.pdf",
  "18-Composition-Reelle.pdf",
].flatMap(realCMaps);

/** Bytes that mean something to a CMap: the brackets of strings and arrays, the keywords, a U+0000, a lone half-pair. */
const FRAGMENTS: readonly Uint8Array[] = [
  "<",
  ">",
  "[",
  "]",
  "<<",
  "beginbfchar",
  "endbfchar",
  "beginbfrange",
  "endbfrange",
  "<0000>",
  "<D800>",
  "<DC00>",
  "<FFFF>",
  "0",
  "F",
].map(latin1);

interface Damage {
  readonly seed: number;
  readonly cut: number;
  readonly writes: readonly { readonly at: number; readonly byte: number }[];
  readonly inserts: readonly { readonly at: number; readonly fragment: number }[];
  /** A hexadecimal string of the CMap (picked by its rank) replaced by a hostile destination. */
  readonly swaps: readonly { readonly rank: number; readonly destination: number }[];
}

/** Destinations a damaged file may declare and nothing may publish: a U+0000, lone half-pairs, a pair reversed. */
const HOSTILE: readonly Uint8Array[] = ["<0000>", "<D800>", "<DC00>", "<0041DBFF>", "<DC00D800>", "<00000041>"].map(
  latin1,
);

/** The spans of the hexadecimal strings of a CMap: `<` not doubled, up to the next `>`. */
function hexSpans(data: Uint8Array): (readonly [number, number])[] {
  const spans: (readonly [number, number])[] = [];
  for (let at = 0; at < data.length; at += 1) {
    if (data[at] !== 0x3c) continue;
    if (data[at + 1] === 0x3c) {
      at += 1;
      continue;
    }
    const end = data.indexOf(0x3e, at);
    if (end < 0) break;
    spans.push([at, end + 1]);
    at = end;
  }
  return spans;
}

function spliced(data: Uint8Array, from: number, to: number, piece: Uint8Array): Uint8Array {
  const next = new Uint8Array(data.length - (to - from) + piece.length);
  next.set(data.subarray(0, from));
  next.set(piece, from);
  next.set(data.subarray(to), from + piece.length);
  return next;
}

const damageArb: fc.Arbitrary<Damage> = fc.record({
  seed: fc.nat(),
  cut: fc.nat(),
  writes: fc.array(fc.record({ at: fc.nat(), byte: fc.integer({ min: 0, max: 255 }) }), { maxLength: 4 }),
  inserts: fc.array(fc.record({ at: fc.nat(), fragment: fc.nat({ max: FRAGMENTS.length - 1 }) }), { maxLength: 3 }),
  swaps: fc.array(fc.record({ rank: fc.nat(), destination: fc.nat({ max: HOSTILE.length - 1 }) }), { maxLength: 3 }),
});

function damaged(damage: Damage): Uint8Array {
  const source = SEEDS[damage.seed % SEEDS.length] as Uint8Array;
  let out: Uint8Array = source.slice(0, damage.cut % 4 === 0 ? source.length : damage.cut % (source.length + 1));
  for (const { rank, destination } of damage.swaps) {
    const spans = hexSpans(out);
    const span = spans[rank % Math.max(1, spans.length)];
    if (span !== undefined) out = spliced(out, span[0], span[1], HOSTILE[destination] as Uint8Array);
  }
  for (const { at, fragment } of damage.inserts) {
    const where = at % (out.length + 1);
    out = spliced(out, where, where, FRAGMENTS[fragment] as Uint8Array);
  }
  for (const { at, byte } of damage.writes) if (out.length > 0) out[at % out.length] = byte;
  return out;
}

describe("readToUnicode - real CMaps of fixtures, damaged", () => {
  it("the seeds are there and read whole", () => {
    // Six distinct CMaps in the three files, of 1 to 52 codes (measured on 24/11/2026).
    expect(SEEDS.length).toBeGreaterThanOrEqual(3);
    for (const seed of SEEDS) expect(readToUnicode(seed).text.size).toBeGreaterThan(0);
  });

  it("damaged bytes give a table or a refusal of ours, never a raw error, and no invented character", () => {
    const seen = { read: 0, refused: 0 };
    fc.assert(
      fc.property(damageArb, (damage) => {
        let text: ReadonlyMap<number, string>;
        try {
          text = readToUnicode(damaged(damage)).text;
        } catch (error) {
          expect(error, "a refusal of ours, never a raw error").toBeInstanceOf(PdfObjectsRefusal);
          seen.refused += 1;
          return;
        }
        for (const [code, value] of text)
          expect(isPublishable(value), `code ${code}: an invented character`).toBe(true);
        seen.read += 1;
      }),
      params(300),
    );
    // Both branches must be exercised. Measured on 24/11/2026 with this seed: 134 of 300 damaged CMaps still read.
    expect(seen.read, "damaged CMaps that still read").toBeGreaterThan(0);
    expect(seen.refused, "damaged CMaps refused").toBeGreaterThan(0);
  });
});

// ---------------------------------------------------------------------------------------------------------------------
// The predefined Unicode CMaps (`UniXXX-UCS2-H`, `-UTF16-H`), whose code IS the character.

describe("unicodeCodes and textOfUnicodeCode - any painted bytes", () => {
  it("never give a lone surrogate nor U+0000, and keep one code per painted unit", () => {
    fc.assert(
      fc.property(
        fc.uint8Array({ maxLength: 64 }),
        fc.constantFrom("ucs2" as const, "utf16" as const),
        (bytes, form) => {
          const codes = unicodeCodes(bytes, form);
          for (const code of codes) {
            const text = textOfUnicodeCode(code) ?? "";
            expect(isPublishable(text), `code ${code.toString(16)}: an invented character`).toBe(true);
          }
          // A pair is one code of four bytes; every other unit, and a lone last byte, one code each.
          const pairs = codes.filter((code) => code > 0xffff).length;
          expect(codes.length).toBe(Math.ceil(bytes.length / 2) - pairs);
        },
      ),
      params(300),
    );
  });
});
